var MAP_IMG="data:image/webp;base64,";
(() => {
 'use strict';
 const $=s=>document.querySelector(s);
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const photo=(name,alt,cls='',eager=false)=>'<img src="assets/'+e(name)+'.webp" alt="'+e(alt)+'" class="'+cls+'" loading="'+(eager?'eager':'lazy')+'" decoding="async">';
 const cat=id=>JR.categories.find(c=>c.id===id);
 const product=id=>JR.products.find(p=>p.id===id);
 const arrow='<span class="arrow" aria-hidden="true">↗</span>';
 let quote=[];
 try{const saved=JSON.parse(localStorage.getItem('junrong-design-quote-v1')||'[]');if(Array.isArray(saved))quote=saved.filter(x=>product(x.id)&&typeof x.option==='string'&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=100000).map(x=>({...x,intent:x.intent==='样品'?'样品':'采购'}));}catch{}
 let currentScene='boutique', currentOption='',currentTab='description',formDraft={},receipt='';
 function persist(){try{localStorage.setItem('junrong-design-quote-v1',JSON.stringify(quote));}catch{}document.querySelectorAll('.quote-count').forEach(x=>x.textContent=quote.length);}
 let toastTimer;
 function toast(msg){$('.toast').textContent=msg;$('.toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('show'),3300);}
 function title(text){document.title=t(text)+(I18N.lang==='zh'?' · 君荣纺织 JUNRONG':' · JUNRONG');}
 function intro(heading,copy){return '<section class="page-intro wrap"><h1>'+heading+'</h1><p>'+copy+'</p></section>';}
 function cta(){return '<section class="project-cta"><h2>'+t('为下一个项目，找到合适的布草。')+'</h2><a class="button light" href="#/inquiry">'+t('开始项目询价')+' <span class="arrow">→</span></a></section>';}
 function process(){return '<section class="section wrap"><div class="process-head"><div><p class="eyeline">02 / BESPOKE</p><h2>'+t('从选型到交付，')+'<br>'+t('让每一步都清晰。')+'</h2></div><p>'+t('围绕实际采购需求，协同确认材质、规格与项目节奏。')+'</p></div><div class="process-grid">'+[[''+t('沟通需求')+'',''+t('空间类型')+' · '+t('数量')+' · '+t('预算')+''],[''+t('确认选型')+'',''+t('材质')+' · '+t('尺寸')+' · '+t('工艺')+''],[''+t('样品评估')+'',''+t('触感')+' · '+t('色差')+' · '+t('洗涤适配')+''],[''+t('订单交付')+'',''+t('确认清单')+' · '+t('排期')+' · '+t('验收')+'']].map((x,i)=>'<div class="process-item"><span class="number">0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div>').join('')+'</div></section>';}
 function paletteBlock(){return '<section class="section wrap palette-section"><p class="eyeline">COLOUR DIRECTIONS / 2025–2026</p><div class="section-head"><h2>'+t('让酒店，有自己的颜色。')+'</h2><a class="text-link" href="配色趋势与图片核对-V2.html">'+t('查看配色研究')+' ↗</a></div><p>'+t('从沙色与摩卡棕，到鼠尾草绿、雾蓝和酒红。按空间选择，先用样品确认。')+'</p><div class="palette-grid">'+JR.colors.map(c=>'<a href="#/products?color='+c.id+'"><span style="background:'+c.hex+'"></span><strong>'+t(c.name)+'</strong><small>'+t(c.use)+'</small></a>').join('')+'</div><p class="note">'+t('趋势启发的选型提案')+' · '+t('屏幕色与实物存在差异；不是现货色卡或销量排名。具体颜色以实物样品与批次确认。')+'</p></section>';}
 function sceneBlock(){const s=JR.scenes.find(x=>x.id===currentScene);return '<section class="scene-section"><div class="scene-photo">'+photo(s.image,t(s.name)+t('空间配套概念图'))+'<span class="image-caption">'+t('空间灵感 · 设计概念图')+'</span></div><div class="scene-copy"><h2>'+t('让布草，')+'<br>'+t('成为空间的一部分。')+'</h2><p>'+t('从商务酒店到精品民宿，以场景、预算与洗涤需求为起点，规划适合的布草配置。')+'</p><div class="scene-tabs" role="tablist" aria-label="'+t('酒店类型')+'">'+JR.scenes.map(x=>'<button role="tab" aria-selected="'+(x.id===s.id)+'" class="'+(x.id===s.id?'active':'')+'" data-scene="'+x.id+'">'+t(x.name)+'</button>').join('')+'</div><p class="scene-tab-text">'+t(s.title)+'</p><a class="button light" href="#/solutions?scene='+s.id+'">'+t('查看配套方案')+' '+arrow+'</a></div></section>';}
 function home(){
  title(''+t('酒店布草与空间配套')+'');
  $('#main').innerHTML='<section class="hero"><div class="hero-copy"><h1>'+t('织就舒适，')+'<br>'+t('款待每一位宾客。')+'</h1><p>'+t('从一间客房，到整座酒店。')+'<br>'+t('为酒店与民宿采购提供全品类布草选型与配套。')+'</p><div class="hero-actions"><a class="button primary" href="#/products">'+t('探索全品类')+' <span class="arrow">→</span></a><a class="text-link" href="#/solutions">'+t('获取项目方案')+' '+arrow+'</a></div><div class="hero-signature">Considered textiles. Exceptional stays.</div></div><div class="hero-image">'+photo('hero',''+t('白色酒店床品与暖木色客房场景')+'','',true)+'</div></section><div class="category-strip"><a href="#/products?category=bed">'+t('客房床品')+'<span>BED LINEN</span></a><a href="#/products?category=bath">'+t('卫浴织物')+'<span>BATH LINEN</span></a><a href="#/products?category=dining">'+t('餐饮与空间')+'<span>TABLE & INTERIOR</span></a></div><section class="section wrap"><div class="section-head"><div><p class="eyeline">01 / COLLECTION</p><h2>'+t('一站配齐，酒店每一处柔软。')+'</h2></div><a class="text-link" href="#/products">'+t('浏览全部产品')+' '+arrow+'</a></div><div class="collection-grid">'+JR.categories.map((c,i)=>'<a class="collection-card" href="#/products?category='+c.id+'"><div class="photo">'+photo(c.image,t(c.name)+t('选型概念'))+'</div><div class="collection-caption"><span class="number">0'+(i+1)+'</span><div><h3>'+t(c.name)+'</h3><p>'+t(c.description)+'</p></div>'+arrow+'</div></a>').join('')+'</div><div class="collection-tail"><span>'+t('按品类选型，也按空间寻找灵感。')+'</span><span>'+t('产品系列为设计规划，实际供应范围待企业确认。')+'</span></div></section>'+clientsHome()+'<div id="home-scene">'+sceneBlock()+'</div>'+paletteBlock()+process()+cta();
 }
 let activeCategory='all',searchTerm='',material='all',colorFilter='all';
 function productCard(p){return '<a class="product-card" href="#/product/'+p.id+'"><div class="photo">'+photo(p.image,t(p.name)+t('概念图'))+'</div><h3>'+t(p.name)+'</h3><div class="product-meta"><span>'+t(cat(p.category).name)+'</span><span>'+e(t(p.color))+' · '+t('查看详情')+' ↗</span></div></a>';}
 function catalogItems(){const items=JR.products.filter(p=>(activeCategory==='all'||p.category===activeCategory)&&(!searchTerm||(t(p.name)+t(cat(p.category).name)+t(p.material)+t(p.color)).toLowerCase().includes(searchTerm.toLowerCase()))&&(material==='all'||p.material===material)&&(colorFilter==='all'||p.colorId===colorFilter));$('#product-results').innerHTML=items.length?items.map(productCard).join(''):'<div class="empty-state"><h3>'+t('暂未找到对应选型')+'</h3><p>'+t('试试其他产品名称，或清除筛选查看全部系列。')+'</p><button class="button outline" data-clear-filters>'+t('清除筛选')+'</button></div>';$('#result-count').textContent=items.length+' '+t('个选型示例')+'';document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x.dataset.category===activeCategory);x.setAttribute('aria-pressed',String(x.dataset.category===activeCategory));});}
 function catalog(params){
  title(''+t('产品中心')+'');activeCategory=cat(params.get('category'))?params.get('category'):'all';searchTerm='';material='all';colorFilter=JR.colors.some(c=>c.id===params.get('color'))?params.get('color'):'all';
  $('#main').innerHTML=intro(''+t('为每一处空间，')+'<br class="mobile-break">'+t('找到合适的织物。')+'',''+t('从客房到餐桌，按品类与采购需求探索。')+'')+'<section class="catalog-shell wrap"><aside class="category-menu" aria-label="'+t('产品分类')+'"><button data-category="all">'+t('全部产品')+' <small>30</small></button>'+JR.categories.map(c=>'<button data-category="'+c.id+'">'+t(c.name)+' <small>05</small></button>').join('')+'</aside><div><div class="catalog-tools"><label class="search"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.7"/><path d="m15.5 15.5 5 5"/></svg><input id="product-search" type="search" placeholder="'+t('搜索产品名称或材质')+'" aria-label="'+t('搜索产品名称或材质')+'"></label><label class="filter-label">'+t('材质')+'<select id="material-filter"><option value="all">'+t('全部')+'</option>'+[...new Set(JR.products.map(p=>p.material))].map(x=>'<option value="'+e(x)+'">'+t(x)+'</option>').join('')+'</select></label><label class="filter-label">'+t('配色')+'<select id="color-filter"><option value="all">'+t('全部')+'</option>'+JR.colors.map(c=>'<option value="'+c.id+'" '+(colorFilter===c.id?'selected':'')+'>'+t(c.name)+'</option>').join('')+'</select></label></div><div class="catalog-meta"><span>'+t('选型示例')+' · '+t('具体规格以确认样品与报价为准')+'</span><span id="result-count"></span></div><div class="product-grid" id="product-results"></div></div></section>';catalogItems();
 }
 const tabs={description:'产品说明',specs:'规格与定制',care:'洗涤建议'};
 function detailTab(p){const c=cat(p.category);const content={
  description:'<p>'+t(p.intro)+'</p><p>'+t('所属系列：')+''+t(c.name)+t('。本系列覆盖')+' '+t(c.description)+t('。页面为选型结构演示，图片为设计概念图；实际款式、材质与供应范围需进一步确认。')+'</p>',
  specs:'<p>'+t('采购沟通建议包含：产品名称、实际成品尺寸、颜色、数量、洗涤条件、使用场景及计划交付时间。')+'</p><p>'+t('纱支、密度、克重、填充成分、工艺、起订量与交期均以企业确认的规格表、样品和正式报价为准。床型是需求参考，不等同于布草成品尺寸。')+'</p>',
  care:'<p>'+t('请根据最终确认的面料成分、成品洗标及洗涤服务商的工艺制定洗护方案。')+'</p><p>'+t('建议正式采购前进行样品洗涤与尺寸变化评估，并沟通收缩率、色牢度及耐洗要求。本演示不提供未经验证的通用温度、漂白或耐洗次数承诺。')+'</p>'
 };return content[currentTab];}
 function detail(id){
  const p=product(id);if(!p){notFound();return}title(p.name);currentOption=p.options.includes('1.8m床')?'1.8m床':p.options[0];currentTab='description';
  $('#main').innerHTML='<div class="wrap"><div class="breadcrumb"><a href="#/">'+t('首页')+'</a> / <a href="#/products">'+t('产品中心')+'</a> / <a href="#/products?category='+p.category+'">'+t(cat(p.category).name)+'</a></div><section class="product-detail"><div>'+photo(p.image,t(p.name)+t('选型概念图'),'detail-photo',true)+'<p class="detail-photo-note">'+t('设计选型概念图')+' · '+t('实际产品以确认样品为准')+'</p></div><div class="detail-summary"><p class="eyeline">'+t(cat(p.category).name)+' / '+cat(p.category).en+'</p><h1>'+t(p.name)+'</h1><p class="intro">'+t(p.intro)+'</p><table class="spec-table"><tbody><tr><td>'+t('材质方向')+'</td><td>'+t(p.material)+t('（选型示例）')+'</td></tr><tr><td>'+t('图示配色')+'</td><td><span class="color-dot" style="background:'+JR.colors.find(c=>c.id===p.colorId).hex+'"></span>'+t(p.color)+t('（样品待确认）')+'</td></tr><tr><td>'+t('所属系列')+'</td><td>'+t(cat(p.category).name)+'</td></tr><tr><td>'+t('规格')+' / '+t('工艺')+'</td><td>'+t('结合使用场景与样品确认')+'</td></tr><tr><td>'+t('采购报价')+'</td><td>'+t('根据规格、数量与交付需求确认')+'</td></tr></tbody></table><span class="option-label">'+t(p.optionLabel)+'</span><div class="options" role="group" aria-label="'+t('选择规格')+'">'+p.options.map(o=>'<button class="'+(o===currentOption?'active':'')+'" data-option="'+e(o)+'" aria-pressed="'+(o===currentOption)+'">'+t(o)+'</button>').join('')+'</div><label class="option-label" for="detail-qty">'+t('预计采购数量（')+''+t(p.unit)+(I18N.lang==='zh'?'）':')')+'</label><input id="detail-qty" class="qty-input" type="number" min="1" max="100000" step="1" value="100" required><div class="detail-actions"><button class="button primary" data-add="'+p.id+'">'+t('加入询价清单')+' <span class="arrow">＋</span></button><button class="button outline" data-sample="'+p.id+'">'+t('申请样品')+'</button></div><p class="note">'+t('选型示例')+' · '+t('具体规格以确认样品与报价为准。')+'<br>'+(p.category==='bed'||p.category==='core'?''+t('床型不等于成品尺寸，需结合床垫与洗涤预缩要求确认。')+'':''+t('具体尺寸、克重、颜色与工艺请在项目需求中补充。')+'')+'</p></div></section><section class="detail-tabs"><div class="tab-list" role="tablist" aria-label="'+t('产品信息')+'">'+Object.entries(tabs).map(([key,label])=>'<button role="tab" aria-selected="'+(key===currentTab)+'" class="'+(key===currentTab?'active':'')+'" data-detail-tab="'+key+'" data-product="'+p.id+'">'+t(label)+'</button>').join('')+'</div><div class="tab-content" role="tabpanel" id="detail-tab-content">'+detailTab(p)+'</div></section></div>'+cta();
 }
 function add(id,option,qty,intent='采购'){const existing=quote.find(x=>x.id===id&&x.option===option&&x.intent===intent);if(existing)existing.qty=Math.min(100000,existing.qty+qty);else quote.push({id,option,qty,intent});persist();}
 function quoteMarkup(){return '<h3>'+t('选型清单')+' / '+String(quote.length).padStart(2,'0')+'</h3><p class="note">'+t('选型示例')+' · '+t('具体规格以确认样品与报价为准。')+'</p>'+(quote.length?'<div class="quote-items">'+quote.map((x,i)=>{const p=product(x.id);return '<article class="quote-item">'+photo(p.image,t(p.name))+'<div><h4><a href="#/product/'+p.id+'">'+t(p.name)+'</a></h4><p>'+e(t(x.option))+' · '+t(x.intent)+'</p><label><input class="line-qty" aria-label="'+e(t(p.name)+t('数量'))+'" data-quantity="'+i+'" type="number" min="1" max="100000" step="1" value="'+x.qty+'"> <span class="note">'+t(p.unit)+'</span></label></div><button class="remove-item" aria-label="'+e(t('移除')+t(p.name))+'" data-remove="'+i+'">×</button></article>';}).join('')+'</div>':'<div class="quote-empty"><p>'+t('还没有选型产品。你可以先探索产品，也可以直接填写项目需求。')+'</p><a class="button outline" href="#/products">'+t('浏览产品')+' '+arrow+'</a></div>')+'<div class="quote-total">'+t('数量与规格可在沟通后调整，最终以正式报价为准。')+'</div>';}
 function field(label,name,type='text',required=false,placeholder=''){return '<label class="form-field"><span>'+label+(required?' <span class="required">*</span>':'')+'</span><input name="'+name+'" type="'+type+'" '+(required?'required ':'')+(type==='number'?'min="1" max="100000" step="1" ':'')+(type==='tel'?'minlength="6" maxlength="30" ':'')+'maxlength="200" placeholder="'+placeholder+'" value="'+e(formDraft[name]||'')+'"></label>';}
 function inquiry(){title(''+t('项目询价')+'');$('#main').innerHTML=intro(''+t('把项目需求，')+'<br class="mobile-break">'+t('交给君荣。')+'',''+t('整理选型与采购信息，开启下一步沟通。')+'')+'<section class="inquiry-grid wrap"><div><h2 class="form-title">'+t('项目需求')+'</h2><form id="inquiry-form"><div class="form-grid">'+field(''+t('公司')+' / '+t('酒店名称')+'','organization','text',true,''+t('请输入公司或酒店名称')+'')+field(''+t('联系人')+'','contact','text',true,''+t('请输入联系人姓名')+'')+field(''+t('联系电话')+'','phone','tel',true,''+t('请输入联系电话')+'')+'<label class="form-field"><span>'+t('项目类型')+'</span><select name="projectType">'+['商务酒店','精品民宿','高端酒店','公寓 / 长住','餐饮 / 宴会','其他'].map(x=>'<option value="'+e(x)+'" '+(formDraft.projectType===x?'selected':'')+'>'+t(x)+'</option>').join('')+'</select></label>'+field(''+t('预计客房数')+'','rooms','number',false,''+t('选填')+'')+field(''+t('计划交付时间')+'','delivery','date')+'<label class="form-field full"><span>'+t('补充需求')+'</span><textarea name="notes" maxlength="3000" placeholder="'+t('品类、数量、规格、预算或洗涤要求')+'">'+e(formDraft.notes||'')+'</textarea></label></div><label class="consent"><input type="checkbox" name="consent" required>'+t('我已确认以上信息可用于本次采购沟通。')+'</label><button class="button primary submit-button" type="submit">'+t('生成询价单')+' <span class="arrow">→</span></button><p class="note">'+t('也可以直接联系销售团队：')+'<a class="text-link" href="mailto:sales@junrongtextiles.com">sales@junrongtextiles.com</a></p></form><div id="receipt-area"></div></div><aside class="quote-panel" id="quote-panel">'+quoteMarkup()+'</aside></section>';}
 function localBrief(s){return t(s.briefBase)+' '+t('配色方向：')+t(s.palette)+t('与中性色；以实物色样确认。');}
 function solutions(params){const sid=params.get('scene');if(JR.scenes.some(s=>s.id===sid))currentScene=sid;title(''+t('空间配套方案')+'');const s=JR.scenes.find(s=>s.id===currentScene);$('#main').innerHTML=intro(''+t('让布草，成为空间的一部分。')+'',''+t('从场景、预算与洗涤需求出发，梳理适合项目的布草配置。')+'')+'<div class="wrap"><div class="scene-page-tabs" role="tablist" aria-label="'+t('酒店类型')+'">'+JR.scenes.map(x=>'<button role="tab" aria-selected="'+(x.id===s.id)+'" class="'+(x.id===s.id?'active':'')+'" data-solution="'+x.id+'">'+t(x.name)+'</button>').join('')+'</div><section class="solution-detail"><div class="scene-photo">'+photo(s.image,t(s.name)+t('空间概念图'),'',true)+'<span class="image-caption">'+t('空间灵感 · 设计概念图，非真实客户案例')+'</span></div><div><p class="eyeline">'+t(s.name)+' / SPACE & TEXTILES</p><h2>'+t(s.title)+'</h2><p>'+t(s.desc)+'</p><p class="note">'+t('配色方向：')+''+t(s.palette)+''+t('与中性色')+' · '+t('下方产品是分项选型，非场景中全部物品的同款承诺。')+'</p><ul class="focus-list">'+s.focus.map(x=>'<li>'+t(x)+'</li>').join('')+'</ul><button class="button primary" data-project="'+s.id+'">'+t('以此方案发起询价')+' '+arrow+'</button><p class="note">'+t('方案为设计示例，需结合实际产品与预算确认。')+'</p></div></section></div><section class="section section-sand"><div class="wrap"><div class="section-head"><h2>'+t('从这些系列开始选型。')+'</h2><a class="text-link" href="#/products">'+t('查看全部产品')+' '+arrow+'</a></div><div class="product-grid compact-grid">'+s.selection.map(id=>productCard(product(id))).join('')+'</div></div></section>'+process()+cta();}
 function custom(){title(''+t('定制服务')+'');$('#main').innerHTML=intro(''+t('让每一份需求，')+'<br>'+t('都有细致的回应。')+'',''+t('以需求沟通、样品确认和清单协同，规划酒店布草的定制路径。')+'')+'<section class="section wrap article-layout"><div><p class="eyeline">BESPOKE / '+t('定制方向')+'</p><h2 style="margin-top:20px">'+t('从材质到细节，')+'<br>'+t('建立一致的体验。')+'</h2></div><div><p>'+t('床型尺寸、空间色彩、织物触感和洗涤条件，都会影响布草的最终选型。我们为网站规划了清晰的需求沟通入口，让采购人员先描述问题，再与供应方确认可行方案。')+'</p><p class="note">'+t('以下为建议业务呈现方式。具体可提供的定制工艺、样品政策、起订量和交期，需由上海君荣纺织品有限公司确认后上线。')+'</p></div></section><section class="wrap">'+[[''+t('尺寸适配')+'',''+t('确认床垫长宽高、实际成品尺寸、包边与预缩要求。')+''],[''+t('材质与触感')+'',''+t('梳理成分、纱支、密度或克重，以及使用与洗涤需求。')+''],[''+t('品牌与色彩')+'',''+t('沟通颜色、织标、刺绣或提花等需求，并评估实际工艺。')+''],[''+t('项目配套')+'',''+t('按空间和房型整理品类、数量、备品与交付批次。')+'']].map((x,i)=>'<article class="service-row"><span class="number">0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></article>').join('')+'</section>'+process()+cta();}
 function about(){title(''+t('关于君荣')+'');const all=clAll(),five=all.filter(h=>h.stars===5).length,logos=CL.brands.filter(b=>b.logo);
  const pillars=[
   [''+t('专业')+'','EXPERTISE',''+t('懂布草，更懂酒店运营。')+'',[''+t('按房型、床型与入住率规划配置，周转量按行业惯用的')+' 3–5 '+t('套测算')+'',''+t('选型兼顾洗涤厂工艺、熨烫效率与补货节奏')+'',''+t('从单店换新到多店开业，都有清晰的品类与数量清单')+'']],
   [''+t('品质')+'','QUALITY',''+t('以五星级酒店的要求，对待每一批货。')+'',[''+t('大货生产前确认样品，按确认样逐批验收')+'',''+t('关注色牢度、缩水率与强力等耐洗表现')+'',''+t('同一项目保持批次间颜色与尺寸一致')+'']],
   [''+t('准时')+'','ON-TIME DELIVERY',''+t('开业日期，不容错过。')+'',[''+t('交付日期在合同中明确约定')+'',''+t('以开业日倒排打样、生产与物流节点')+'',''+t('关键节点主动同步进度，必要时分批交付')+'']],
   [''+t('定制')+'','BESPOKE',''+t('让布草成为酒店品牌的一部分。')+'',[''+t('酒店标识刺绣、提花与织标')+'',''+t('按品牌视觉规范开发专属配色')+'',''+t('先打样确认，再进入批量生产')+'']]];
  const steps=[[''+t('需求诊断')+'',''+t('酒店类型')+' · '+t('房量')+' · '+t('空间风格')+''],[''+t('方案与报价')+'',''+t('品类清单')+' · '+t('规格')+' · '+t('预算')+''],[''+t('样品确认')+'',''+t('触感')+' · '+t('色样')+' · '+t('洗涤测试')+''],[''+t('生产与质检')+'',''+t('按确认样生产与验收')+''],[''+t('交付与补货')+'',''+t('准时交付')+' · '+t('长期补货')+'']];
  $('#main').innerHTML=
  '<section class="about-hero"><div class="about-hero-copy"><p class="eyeline">ABOUT JUNRONG / '+t('关于君荣')+'</p><h1>'+t('为款待而织。')+'</h1><p class="about-lead">'+t('上海君荣纺织品有限公司，专注于酒店布草的全品类供应。从北京饭店、和平饭店到上海金茂君悦大酒店，君荣曾为百余家星级酒店提供布草。')+'</p><p>'+t('宾客记住一家酒店，往往从躺下的那一刻开始：床单的垂坠、毛巾的厚度、浴袍的分量。我们把这些细节，当作款待的一部分来完成。')+'</p><div class="hero-signature">Considered textiles. Exceptional stays.</div></div><div class="about-hero-image">'+photo('scene-luxury',''+t('高端酒店客房布草场景')+'','',true)+'</div></section>'+
  '<section class="wrap client-stats"><div><strong>'+all.length+'</strong><span>'+t('星级酒店客户')+'</span></div><div><strong>'+five+'</strong><span>'+t('五星级酒店')+'</span></div><div><strong>'+CL.brands.length+'</strong><span>'+t('国际酒店品牌')+'</span></div><div><strong>6</strong><span>'+t('大品类全空间配套')+'</span></div></section>'+
  '<section class="section wrap"><div class="about-statement" style="border-top:0;padding-top:0"><div><p class="eyeline">OUR PHILOSOPHY / '+t('品牌理念')+'</p><h2>'+t('布草不是消耗品，')+'<br>'+t('是酒店品质的')+'<br>'+t('日常证明。')+'</h2></div><div><p>'+t('一家酒店每天要更换成百上千件布草。它们经历高温洗涤、反复熨烫和频繁周转，却必须在每一位宾客面前保持如新的触感与洁净。')+'</p><p>'+t('君荣相信，真正的品质不只体现在第一天，而是体现在第一百次洗涤之后。所以我们从选型开始，就同时考虑宾客的体验和酒店的运营：面料是否耐洗，尺寸是否适配，颜色能否稳定补货。')+'</p><p>'+t('这是我们服务星级酒店多年形成的工作方式，也是我们对每一个新项目的承诺。')+'</p></div></div></section>'+
  '<section class="section section-sand"><div class="wrap"><div class="section-head"><div><p class="eyeline">THE JUNRONG STANDARD / '+t('君荣标准')+'</p><h2>'+t('专业、品质、准时，')+'<br>'+t('是合作的基本盘。')+'</h2></div></div><div class="pillar-grid">'+pillars.map((p,i)=>'<article class="pillar"><span class="number">0'+(i+1)+'</span><p class="pillar-en">'+p[1]+'</p><h3>'+p[0]+'</h3><p class="pillar-lead">'+p[2]+'</p><ul>'+p[3].map(x=>'<li>'+x+'</li>').join('')+'</ul></article>').join('')+'</div></div></section>'+
  '<section class="scene-section about-proof"><div class="scene-photo">'+photo('scene-business',''+t('星级酒店客房概念图')+'')+'</div><div class="scene-copy"><p class="eyeline" style="color:inherit;opacity:.8">TRUSTED BY / '+t('合作见证')+'</p><h2>'+t('以五星级标准，')+'<br>'+t('服务每一个项目。')+'</h2><p>'+t('香格里拉、瑞吉、')+'JW '+t('万豪、君悦、希尔顿、喜来登、威斯汀、索菲特……君荣服务过的星级酒店中，有')+' '+five+' '+t('家五星级酒店，涉及')+' '+CL.brands.length+' '+t('个国际酒店品牌；也包括北京饭店、和平饭店、中国大酒店等城市地标。')+'</p><a class="button light" href="#/clients">'+t('查看合作酒店')+' <span class="arrow">→</span></a></div></section>'+
  '<section class="section wrap"><div class="brand-wall">'+logos.slice(0,10).map(brandTile).join('')+'</div></section>'+
  '<section class="section wrap"><div class="about-statement" style="border-top:0;padding-top:0"><div><p class="eyeline">LEADERSHIP'+(I18N.lang==='en'?'':' / '+t('管理团队'))+'</p><h2>'+t('梅莉君')+'</h2><p class="leader-role">'+t('总经理')+'</p></div><div><p>'+t('梅莉君女士担任上海君荣纺织品有限公司总经理，全面负责公司经营管理，带领团队为酒店客户提供高品质的纺织品与服务。')+'</p><p><a class="text-link" href="mailto:lily.mei@junrongtextiles.com">lily.mei@junrongtextiles.com</a></p></div></div></section>'+
  '<section class="section wrap" style="padding-top:0"><div class="process-head"><div><p class="eyeline">WORKING WITH US / '+t('合作方式')+'</p><h2>'+t('从第一次沟通，')+'<br>'+t('到长期补货。')+'</h2></div><p>'+t('每个项目都有专人跟进，节点清晰，进度可查。')+'</p></div><div class="process-grid five">'+steps.map((x,i)=>'<div class="process-item"><span class="number">0'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div>').join('')+'</div><p class="about-factory-link"><a class="text-link" href="#/factory">'+t('走进生产现场')+' '+arrow+'</a></p><p class="note about-note">'+t('客户名录为君荣过往业绩，品牌标志归各自权利人所有。网站酒店场景图为设计概念图，并非上述客户实景。')+'</p></section>'+
  '<section class="section wrap"><div class="about-statement" style="border-top:0;padding-top:0"><div><p class="eyeline">FIND US'+(I18N.lang==='en'?'':' / '+t('我们的位置'))+'</p><h2>'+t('我们在上海嘉定。')+'</h2><p class="leader-role">'+t('公司地址')+'</p><p>'+t('上海市嘉定区银裕路135号')+'</p><p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%98%89%E5%AE%9A%E5%8C%BA%E9%93%B6%E8%A3%95%E8%B7%AF135%E5%8F%B7" target="_blank" rel="noopener">'+t('在 Google 地图上查看')+' ↗</a> <a class="text-link" href="https://www.amap.com/search?query=%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%98%89%E5%AE%9A%E5%8C%BA%E9%93%B6%E8%A3%95%E8%B7%AF135%E5%8F%B7" target="_blank" rel="noopener">'+t('在高德地图查看')+' ↗</a></p></div><div><a href="https://www.google.com/maps/search/?api=1&query=%E4%B8%8A%E6%B5%B7%E5%B8%82%E5%98%89%E5%AE%9A%E5%8C%BA%E9%93%B6%E8%A3%95%E8%B7%AF135%E5%8F%B7" target="_blank" rel="noopener"><img class="map-frame" src="'+MAP_IMG+'" width="1000" height="600" alt="'+t('君荣纺织公司位置地图')+'" loading="lazy"></a></div></div></section>'+cta();}
 function factory(){title(''+t('工厂实景')+'');
  const rows=[
   ['factory-weaving',''+t('织造')+'','WEAVING',''+t('从一匹坯布开始。')+'',''+t('整排织机并列运转，坯布从机台卷出，成卷待下一道工序。布草的手感与耐洗度，先由织造这一步决定。')+'',[''+t('整排织机，机位逐台编号')+'',''+t('白坯布成卷下机，进入后续工序')+''],''+t('织机车间')+' · '+t('白坯布下机')+''],
   ['factory-inspect',''+t('展开检视')+'','FABRIC CHECK',''+t('整幅展开，逐幅看过。')+'',''+t('大幅面布料上架后整幅展开，由人工逐幅查看门幅、色泽与表面。问题在裁剪之前发现，比成品之后再返工要省得多。')+'',[''+t('整幅上架，目视检查布面')+'',''+t('灰色系布料，现场自然光与灯光并用')+''],''+t('布料上架展开检视')+''],
   ['factory-sewing',''+t('缝制')+'','SEWING',''+t('一件件缝出来的细节。')+'',''+t('宽敞的车间里，工人在工业缝纫机前按工位作业，裁片、半成品分区堆放。包边、拼缝、锁边，每一道都靠手上的功夫。')+'',[''+t('多工位并行，工业缝纫机整排布置')+'',''+t('大窗采光，作业环境明亮')+''],''+t('缝制车间')+''],
   ['factory-stock',''+t('成品整理')+'','FINISHING',''+t('叠放整齐，才好点数、才好验收。')+'',''+t('缝制完成的成品按品类整齐叠放，边角对齐，便于逐摞点数与抽检。酒店要的是一批货的整齐划一，这一步看得最清楚。')+'',[''+t('成品分摞码放，层层对齐')+'',''+t('便于数量核对与出货前抽检')+''],''+t('成品叠放区')+''],
   ['factory-packing',''+t('打包待发')+'','PACKING & DISPATCH',''+t('封包上托，按项目发出。')+'',''+t('成品分袋封包，系带固定，垫板码放在库区，包上标注品名与数量。按酒店项目分批备货，开业前的交付节点才有保障。')+'',[''+t('封包')+' + '+t('托盘码放，便于装车')+'',''+t('包装标注品名，分项目备货')+''],''+t('成品库区')+' · '+t('封包待发')+'']];
  $('#main').innerHTML=
  '<section class="fac-hero"><div class="fac-hero-copy"><p class="eyeline">FACTORY / '+t('工厂实景')+'</p><h1>'+t('从织机到出货，')+'<br>'+t('每一步都看得见。')+'</h1><p class="fac-lead">'+t('这些是君荣合作生产现场的真实照片：织造、检视、缝制、整理、打包，一件酒店布草从布到货的全过程。')+'</p></div><div class="fac-steps">'+rows.map((r,i)=>'<a href="#fac-'+i+'" data-fac="'+i+'"><span class="fs-img">'+photo(r[0],r[6])+'</span><span class="fs-t"><b>0'+(i+1)+'</b>'+r[1]+'</span></a>').join('')+'</div></section>'+
  '<section class="fac-list">'+rows.map((r,i)=>'<article class="fac-row'+(i%2?' rev':'')+'" id="fac-'+i+'"><figure class="fac-photo">'+photo(r[0],r[6])+'<figcaption>'+r[6]+'</figcaption></figure><div class="fac-copy"><span class="number">0'+(i+1)+'</span><p class="eyeline">'+r[2]+'</p><h2>'+r[1]+(I18N.lang==='en'?':':'：')+'<br>'+r[3]+'</h2><p>'+r[4]+'</p><ul>'+r[5].map(x=>'<li>'+x+'</li>').join('')+'</ul></div></article>').join('')+'</section>'+
  '<section class="section wrap fac-foot"><div><p class="eyeline">FROM FLOOR TO FLOOR / '+t('从车间到客房')+'</p><h2>'+t('看得见的现场，')+'<br>'+t('才有看得见的交期。')+'</h2></div><div><p>'+t('欢迎酒店采购与工程团队预约到访，现场核对工艺、样品与备货情况。')+'</p><a class="button primary" href="#/inquiry">'+t('预约看厂')+' · '+t('获取报价')+' <span class="arrow">→</span></a></div></section>'+
  '<p class="wrap note fac-note">'+t('照片为生产现场实拍，仅做影调与尺寸的统一处理，未改动画面内容。')+'</p>'+cta();
  document.querySelectorAll('[data-fac]').forEach(a=>a.addEventListener('click',ev=>{ev.preventDefault();const t=document.getElementById('fac-'+a.dataset.fac);if(t)t.scrollIntoView({behavior:'smooth'});}));}
 function notFound(){title(''+t('页面未找到')+'');$('#main').innerHTML='<section class="section wrap empty-state"><h1>'+t('这个页面暂不存在。')+'</h1><p>'+t('可以从产品中心继续探索。')+'</p><a href="#/products" class="button primary">'+t('返回产品中心')+'</a></section>';}
 function saveForm(){const f=$('#inquiry-form');if(f)formDraft=Object.fromEntries(new FormData(f).entries());}
 /* ---- 合作酒店 ---- */
 const CL=window.JR_CLIENTS||{brands:[],landmarks:[],regions:[]};
 const clAll=()=>CL.regions.flatMap(r=>r.hotels.map(h=>({name:h[0],stars:h[1],region:r.id,regionName:r.name})));
 const starText=n=>'★'.repeat(n);
 let clRegion='all',clStars=0,clTerm='';
 function brandTile(b){const cn=I18N.lang==='en'?'':t(b.cn);if(!b.logo)return '<div class="brand-tile"><span class="hb-name">'+e(b.name)+'</span>'+(cn?'<span class="hb-cn">'+e(cn)+'</span>':'')+'</div>';const w=Math.min(190,Math.round(Math.sqrt(4600*b.ar)));return '<div class="brand-tile has-logo"><img class="hb-logo" src="assets/logos/'+e(b.logo)+'.svg?v=1" alt="'+e(b.name)+' '+t('标志')+'" style="--w:'+w+'" loading="lazy" decoding="async"><span class="hb-cn">'+e(t(b.cn))+'</span></div>';}
 function clientsHome(){const five=clAll().filter(h=>h.stars===5).length;return '<section class="section wrap clients-home"><div class="section-head"><div><p class="eyeline">TRUSTED BY / '+t('合作酒店')+'</p><h2>'+t('曾为百余家星级酒店，')+'<br>'+t('织就款待。')+'</h2></div><a class="text-link" href="#/clients">'+t('查看合作酒店')+' '+arrow+'</a></div><div class="brand-wall">'+CL.brands.slice(0,10).map(b=>brandTile(b)).join('')+'</div><p class="clients-tail">'+t('北京饭店')+' · '+t('和平饭店')+' · '+t('上海金茂君悦大酒店')+' · '+t('中国大酒店')+' · '+t('广州花园酒店')+' · '+t('深圳香格里拉大酒店')+' '+t('等')+' '+clAll().length+' '+t('家宣传册收录客户，其中五星级')+' '+five+' '+t('家。')+'</p></section>';}
 function clientsList(){const q=clTerm.trim();const list=clAll().filter(h=>(clRegion==='all'||h.region===clRegion)&&(!clStars||h.stars===clStars)&&(!q||t(h.name).includes(q)));const box=$('#client-list');if(!box)return;$('#client-count').textContent=''+t('共')+' '+list.length+' '+t('家')+'';
  if(!list.length){box.innerHTML='<p class="client-empty">'+t('没有符合条件的酒店。')+'<button class="text-link" data-client-reset>'+t('清除筛选')+'</button></p>';return;}
  const groups=(clRegion==='all'?CL.regions.filter(r=>list.some(h=>h.region===r.id)):CL.regions.filter(r=>r.id===clRegion));
  box.innerHTML=groups.map(r=>{const hs=list.filter(h=>h.region===r.id).sort((a,b)=>b.stars-a.stars);return '<div class="client-region"><h3>'+t(r.name)+'<span>'+hs.length+' '+t('家')+'</span></h3><ul class="client-grid">'+hs.map(h=>'<li><span>'+e(t(h.name))+'</span><span class="stars" aria-label="'+h.stars+''+t('星级')+'">'+starText(h.stars)+'</span></li>').join('')+'</ul></div>';}).join('');}
 function clients(){title(''+t('合作酒店')+'');const all=clAll();const five=all.filter(h=>h.stars===5).length;clRegion='all';clStars=0;clTerm='';
  $('#main').innerHTML=intro(''+t('曾为百余家星级酒店，')+'<br>'+t('织就款待。')+'',''+t('上海君荣纺织品有限公司历年服务的部分星级宾馆与酒店客户')+' · '+e(t(CL.source)))+
  '<section class="wrap client-stats"><div><strong>'+all.length+'</strong><span>'+t('宣传册收录酒店客户')+'</span></div><div><strong>'+five+'</strong><span>'+t('其中五星级酒店')+'</span></div><div><strong>'+CL.brands.length+'</strong><span>'+t('国际酒店品牌')+'</span></div><div><strong>'+CL.regions.length+'</strong><span>'+t('重点区域')+' · '+CL.regions.map(r=>t(r.name)).join(' / ')+'</span></div></section>'+
  '<section class="section wrap"><div class="section-head"><div><p class="eyeline">01 / HOTEL BRANDS</p><h2>'+t('国际酒店品牌')+'</h2></div></div><div class="brand-wall">'+CL.brands.map(b=>brandTile(b)).join('')+'</div></section>'+
  '<section class="section section-sand"><div class="wrap"><div class="section-head"><div><p class="eyeline">02 / LANDMARK HOTELS</p><h2>'+t('代表酒店')+'</h2></div><p class="note">'+t('城市地标与历史名店，见证布草的分寸与品质。')+'</p></div><ul class="landmark-grid">'+CL.landmarks.map((l,i)=>'<li><span class="number">'+String(i+1).padStart(2,'0')+'</span><div><h3>'+e(I18N.lang==='en'?l.en:t(l.name))+'</h3>'+(I18N.lang==='en'?'':'<p>'+e(l.en)+'</p>')+'</div><span class="city">'+e(t(l.city))+'</span></li>').join('')+'</ul></div></section>'+
  '<section class="section wrap"><div class="section-head"><div><p class="eyeline">03 / CLIENT DIRECTORY</p><h2>'+t('星级酒店客户名录')+'</h2></div><span class="note" id="client-count"></span></div><div class="client-filters"><div class="client-chips" role="group" aria-label="'+t('地区')+'">'+[['all',''+t('全部地区')+'']].concat(CL.regions.map(r=>[r.id,t(r.name)])).map(([id,n])=>'<button class="chip'+(id==='all'?' active':'')+'" data-client-region="'+id+'">'+n+'</button>').join('')+'</div><div class="client-chips" role="group" aria-label="'+t('星级')+'">'+[[0,''+t('全部星级')+''],[5,''+t('五星级')+''],[4,''+t('四星级')+''],[3,''+t('三星级')+'']].map(([s,n])=>'<button class="chip'+(s===0?' active':'')+'" data-client-stars="'+s+'">'+n+'</button>').join('')+'</div><label class="client-search"><span class="sr-only">'+t('搜索酒店')+'</span><input id="client-search" type="search" placeholder="'+t('搜索酒店名称')+'"></label></div><div id="client-list"></div><p class="note client-note">'+t('以上为君荣纺织历年服务过的部分星级宾馆、酒店客户，部分酒店此后已更名或调整星级，名录不代表当前合作关系。品牌标志取自各品牌官网，为配合本站视觉统一处理为单色；酒店品牌、名称与标志归各自权利人所有。')+'</p></section>'+cta();
  clientsList();}
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-client-region],[data-client-stars],[data-client-reset]');if(!b)return;
  if(b.hasAttribute('data-client-reset')){clRegion='all';clStars=0;clTerm='';const s=$('#client-search');if(s)s.value='';}
  if(b.dataset.clientRegion)clRegion=b.dataset.clientRegion;if(b.dataset.clientStars!==undefined)clStars=Number(b.dataset.clientStars);
  document.querySelectorAll('[data-client-region]').forEach(x=>x.classList.toggle('active',x.dataset.clientRegion===clRegion));
  document.querySelectorAll('[data-client-stars]').forEach(x=>x.classList.toggle('active',Number(x.dataset.clientStars)===clStars));clientsList();});
 document.addEventListener('input',ev=>{if(ev.target.id==='client-search'){clTerm=ev.target.value;clientsList();}});
 function route(){saveForm();const [path,query]=(location.hash.slice(1)||'/').split('?');const params=new URLSearchParams(query||'');let active=path.split('/')[1]||'home';if(path==='/')home();else if(path==='/products')catalog(params);else if(path.startsWith('/product/')){detail(path.split('/')[2]);active='products';}else if(path==='/solutions')solutions(params);else if(path==='/custom')custom();else if(path==='/clients')clients();else if(path==='/about')about();else if(path==='/factory')factory();else if(path==='/inquiry')inquiry();else notFound();document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===active);if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('.mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');persist();window.scrollTo({top:0,behavior:'instant'});}
 document.addEventListener('click',ev=>{
  if(ev.target.closest('.skip-link')){ev.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
  const b=ev.target.closest('button');if(!b)return;
  if(b.classList.contains('menu-toggle')){const open=$('.mobile-nav').hidden;$('.mobile-nav').hidden=!open;b.setAttribute('aria-expanded',String(open));}
  if(b.hasAttribute('data-category')){activeCategory=b.dataset.category;catalogItems();}
  if(b.hasAttribute('data-clear-filters')){activeCategory='all';searchTerm='';material='all';colorFilter='all';$('#color-filter').value='all';$('#product-search').value='';$('#material-filter').value='all';catalogItems();}
  if(b.hasAttribute('data-scene')){currentScene=b.dataset.scene;$('#home-scene').innerHTML=sceneBlock();}
  if(b.hasAttribute('data-solution')){location.hash='/solutions?scene='+b.dataset.solution;}
  if(b.hasAttribute('data-option')){currentOption=b.dataset.option;document.querySelectorAll('[data-option]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});}
  if(b.hasAttribute('data-detail-tab')){currentTab=b.dataset.detailTab;document.querySelectorAll('[data-detail-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b));});$('#detail-tab-content').innerHTML=detailTab(product(b.dataset.product));}
  if(b.hasAttribute('data-add')||b.hasAttribute('data-sample')){const input=$('#detail-qty');if(!input.reportValidity())return;const sample=b.hasAttribute('data-sample');add(b.dataset.add||b.dataset.sample,currentOption+' / '+product(b.dataset.add||b.dataset.sample).color,sample?1:Number(input.value),sample?'样品':'采购');toast(sample?''+t('已加入样品需求，请补充项目信息。')+'':''+t('已加入询价清单，可继续选品或获取报价。')+'');if(sample)location.hash='/inquiry';}
  if(b.hasAttribute('data-remove')){quote.splice(Number(b.dataset.remove),1);persist();$('#quote-panel').innerHTML=quoteMarkup();invalidateReceipt();toast(''+t('已移除该选型。')+'');}
  if(b.hasAttribute('data-project')){const s=JR.scenes.find(x=>x.id===b.dataset.project);formDraft={...formDraft,projectType:s.name,notes:localBrief(s)};location.hash='/inquiry';}
  if(b.hasAttribute('data-download')){downloadReceipt();}
  if(b.hasAttribute('data-edit-form')){$('#inquiry-form').scrollIntoView({behavior:'smooth'});$('#inquiry-form input').focus();}
 });
 function invalidateReceipt(){receipt='';const area=$('#receipt-area');if(area)area.innerHTML='';}
 document.addEventListener('input',ev=>{if(ev.target.id==='product-search'){searchTerm=ev.target.value;catalogItems();}if(ev.target.closest('#inquiry-form'))invalidateReceipt();if(ev.target.hasAttribute('data-quantity')){const input=ev.target;const n=Number(input.value);if(input.checkValidity()&&Number.isInteger(n)&&n>0){quote[Number(input.dataset.quantity)].qty=n;persist();invalidateReceipt();}}});
 document.addEventListener('change',ev=>{if(ev.target.id==='color-filter'){colorFilter=ev.target.value;catalogItems();}if(ev.target.id==='material-filter'){material=ev.target.value;catalogItems();}if(ev.target.hasAttribute('data-quantity')&&!ev.target.checkValidity()){ev.target.reportValidity();ev.target.value=quote[Number(ev.target.dataset.quantity)].qty;}});
 document.addEventListener('submit',ev=>{if(ev.target.id!=='inquiry-form')return;ev.preventDefault();if(!ev.target.reportValidity())return;saveForm();receipt=makeReceipt();$('#receipt-area').innerHTML='<section class="success-box" role="status"><h3>'+t('询价单已在本地生成。')+'</h3><p>'+t('已整理')+' '+e(formDraft.organization)+' '+t('的项目需求与')+' '+quote.length+' '+t('项产品选型。尚未发送给上海君荣纺织品有限公司。')+'</p><button class="button primary" data-download>'+t('下载询价单')+' .md ↓</button><button class="button outline" data-edit-form>'+t('继续编辑')+'</button></section>';$('#receipt-area').scrollIntoView({behavior:'smooth',block:'center'});});
 function makeReceipt(){const sep=I18N.lang==='en'?' | ':'｜',col=I18N.lang==='en'?': ':'：';let lines=['# '+t('上海君荣纺织品有限公司')+' · '+t('项目询价单')+'','','## '+t('项目需求')+'',''];for(const [key,label] of Object.entries({organization:''+t('公司')+' / '+t('酒店名称')+'',contact:''+t('联系人')+'',phone:''+t('联系电话')+'',projectType:''+t('项目类型')+'',rooms:''+t('预计客房数')+'',delivery:''+t('计划交付时间')+'',notes:''+t('补充需求')+''}))lines.push('- '+label+col+(formDraft[key]||''+t('待确认')+''));lines.push('','## '+t('产品选型')+'','');if(!quote.length)lines.push(''+t('未指定产品，按项目需求沟通。')+'');for(const x of quote){const p=product(x.id);lines.push('- '+t(p.name)+sep+t(x.option)+sep+x.qty+t(p.unit)+sep+t(x.intent));}lines.push('','## '+t('待沟通事项')+'','','- '+t('实际材质、规格、工艺和数量')+'','- '+t('起订量、样品政策与费用')+'','- '+t('交付时间、物流、发票与付款条件')+'','- '+t('洗涤要求与验收方式')+'','',''+t('个人信息仅用于本次采购沟通，请按实际需要妥善保管。')+'');return lines.join('\n');}
 function downloadReceipt(){if(!receipt)return;const url=URL.createObjectURL(new Blob([receipt],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=''+t('君荣纺织')+'-'+t('项目询价单')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 window.addEventListener('hashchange',route);
 window.__jrRerender=route;
 route();
})();
